export function primes_up_to(n: number): number[] {
  if (n < 2) return [];
  const limit = Math.floor(n);
  const sieve = new Array<boolean>(limit + 1).fill(true);
  sieve[0] = false;
  sieve[1] = false;
  for (let p = 2; p * p <= limit; p++) {
    if (sieve[p]) {
      for (let m = p * p; m <= limit; m += p) sieve[m] = false;
    }
  }
  const out: number[] = [];
  for (let i = 2; i <= limit; i++) if (sieve[i]) out.push(i);
  return out;
}
